  function next(){const a=1+Math.floor(Math.random()*12),b=1+Math.floor(Math.random()*12),ops=['+','−','×'],op=ops[Math.floor(Math.random()*ops.length)],ans=op==='+'?a+b:op==='−'?a-b:a*b;let vals=[ans,ans+1,ans-1,ans+(Math.random()<.5?2:-2)].sort(()=>Math.random()-.5);q={text:`${a} ${op} ${b} = ?`,ans};buttons=vals.map((v,i)=>({x:150+(i%2)*310,y:270+Math.floor(i/2)*90,w:280,h:65,v}))}next();
