  for(let i=0;i<path.length;i++){const [r,c]=path[i],prev=i?code(dir(path[i],path[i-1])):'L',next=i<path.length-1?code(dir(path[i],path[i+1])):'D',pair=[prev,next].sort().join('');let kind,target;if(pair==='LR'){kind='straight';target=0}else if(pair==='DU'){kind='straight';target=1}else{kind='elbow';target={'RU':0,'DL':1,'DR':2,'LU':3}[pair]}tiles[r][c]={kind,target,rot:seededInt(rng,0,3)}}
