function match3Game(s){
  const R=8,C=8,K=6,colors=['#ff5f7b','#53cfff','#ffe05e','#64db86','#a877ff','#ff9e4c'];let selected=null,moves=20,score=0,target=800+s.level*40,cell=52,ox=242,oy=70,g;
  function matches(board=g){const set=new Set();for(let r=0;r<R;r++)for(let c=0;c<C;c++){if(c<C-2&&board[r][c]===board[r][c+1]&&board[r][c]===board[r][c+2])for(let k=c;k<C&&board[r][k]===board[r][c];k++)set.add(`${r},${k}`);if(r<R-2&&board[r][c]===board[r+1][c]&&board[r][c]===board[r+2][c])for(let k=r;k<R&&board[k][c]===board[r][c];k++)set.add(`${k},${c}`)}return set}
  function hasMove(){for(let r=0;r<R;r++)for(let c=0;c<C;c++)for(const[dr,dc]of[[1,0],[0,1]]){const nr=r+dr,nc=c+dc;if(nr>=R||nc>=C)continue;[g[r][c],g[nr][nc]]=[g[nr][nc],g[r][c]];const ok=matches().size>0;[g[r][c],g[nr][nc]]=[g[nr][nc],g[r][c]];if(ok)return true}return false}
  function makeBoard(){const rng=seedForLevel(s,258);do{g=Array.from({length:R},(_,r)=>Array.from({length:C},(_,c)=>{let v;do v=Math.floor(rng()*K);while((c>1&&g?.[r]?.[c-1]===v&&g[r][c-2]===v)||(r>1&&g?.[r-1]?.[c]===v&&g[r-2][c]===v));return v}))}while(!hasMove())}makeBoard();
  function resolve(){let cascades=0;while(cascades++<12){const m=matches();if(!m.size)break;score+=m.size*50*cascades;for(const q of m){const[r,c]=q.split(',').map(Number);g[r][c]=-1}for(let c=0;c<C;c++){const vals=[];for(let r=R-1;r>=0;r--)if(g[r][c]>=0)vals.push(g[r][c]);for(let r=R-1,i=0;r>=0;r--,i++)g[r][c]=i<vals.length?vals[i]:Math.floor(Math.random()*K)}}if(!hasMove())makeBoard();return cascades>1}
  function choose(r,c){if(r<0||r>=R||c<0||c>=C)return;if(selected===null){selected=[r,c];return}if(Math.abs(r-selected[0])+Math.abs(c-selected[1])!==1){selected=[r,c];return}const[a,b]=selected;[g[a][b],g[r][c]]=[g[r][c],g[a][b]];if(!matches().size)[g[a][b],g[r][c]]=[g[r][c],g[a][b]];else{moves--;resolve()}selected=null;if(score>=target)completeLevel(score);else if(moves<=0)failLevel(score)}
  return{pointer(p,t){if(t==='pointerdown')choose(Math.floor((p.y-oy)/cell),Math.floor((p.x-ox)/cell))},draw(c){bg(c,'#402052');for(let r=0;r<R;r++)for(let col=0;col<C;col++)circle(c,ox+(col+.5)*cell,oy+(r+.5)*cell,21,colors[g[r][col]],selected&&selected[0]===r&&selected[1]===col?'#fff':'');txt(c,`Score ${score}/${target} • Moves ${moves} • No free starting matches`,450,38,20)}}
}

function robotCodeGame(s){
  const R=6,C=8,rng=seedForLevel(s,1021),map=Array.from({length:R},(_,r)=>Array.from({length:C},(_,c)=>(r===0||c===0||r===R-1||c===C-1)?'#':' '));for(let r=1;r<R-1;r++)for(let c=1;c<C-1;c++)if(rng()<.34)map[r][c]='#';const start={r:1,c:1,d:1},battery={r:1+seededInt(rng,0,R-3),c:1+seededInt(rng,1,C-3)},goal={r:R-2,c:C-2};if(battery.r===start.r&&battery.c===start.c)battery.c=3;
  function carve(a,b,hFirst){let r=a.r,c=a.c;map[r][c]=' ';const horizontal=()=>{while(c!==b.c){c+=Math.sign(b.c-c);map[r][c]=' '}};const vertical=()=>{while(r!==b.r){r+=Math.sign(b.r-r);map[r][c]=' '}};hFirst?(horizontal(),vertical()):(vertical(),horizontal())}
  carve(start,battery,s.level%2===0);carve(battery,goal,s.level%3===0);map[battery.r][battery.c]='B';map[goal.r][goal.c]='G';const program=[];let robot={...start},running=false,pc=0,timer=0,collected=false;const cmds=['MOVE','LEFT','RIGHT'],limit=20+Math.floor(s.level/8);
  function add(i){if(program.length<limit)program.push(i)}function run(){robot={...start};pc=0;collected=false;running=true}function step(){if(pc>=program.length){running=false;return}const cmd=program[pc++];if(cmd===1)robot.d=(robot.d+3)%4;else if(cmd===2)robot.d=(robot.d+1)%4;else{const dirs=[[-1,0],[0,1],[1,0],[0,-1]],d=dirs[robot.d],nr=robot.r+d[0],nc=robot.c+d[1];if(map[nr]?.[nc]!=='#'){robot.r=nr;robot.c=nc;if(map[nr][nc]==='B')collected=true;if(map[nr][nc]==='G'&&collected){running=false;completeLevel(2800-program.length*40)}}}}
  return{keyDown(k){if(k==='Space')run();if(k==='Enter'||k==='Backspace')program.pop()},pointer(p,t){if(t!=='pointerdown')return;if(p.y>430){const i=Math.floor((p.x-170)/150);if(i<3)add(i);else if(i===3)run();else program.pop()}},update(dt){if(running){timer+=dt;if(timer>.35){timer=0;step()}}},draw(c){bg(c,'#18283b');const cell=65,ox=190,oy=65;for(let r=0;r<map.length;r++)for(let col=0;col<map[r].length;col++){rect(c,ox+col*cell,oy+r*cell,cell,cell,map[r][col]==='#'?'#34475a':'#d7e4ea','#758695');if(map[r][col]==='B'&&!collected)txt(c,'⚡',ox+(col+.5)*cell,oy+(r+.68)*cell,28);if(map[r][col]==='G')txt(c,'★',ox+(col+.5)*cell,oy+(r+.68)*cell,28,'#5bdc82')}txt(c,['▲','▶','▼','◀'][robot.d],ox+(robot.c+.5)*cell,oy+(robot.r+.68)*cell,30,'#ff5e7b');['MOVE','LEFT','RIGHT','RUN','UNDO'].forEach((v,i)=>{rect(c,170+i*150,440,130,50,'#3b5d7a');txt(c,v,235+i*150,473,16)});txt(c,`${program.map(i=>cmds[i]).join(' → ')||'Program is empty'}  (${program.length}/${limit})`,450,415,18)}}
}
